class Solution {
public:
    int compress(vector<char>& chars) {
        int n = chars.size(), w = 0, i = 0;
        while (i < n) {
            int j = i;
            while (j < n && chars[j] == chars[i]) j++;
            chars[w++] = chars[i];
            int run = j - i;
            if (run > 1) {
                string digits = to_string(run);
                for (char d : digits) chars[w++] = d;
            }
            i = j;
        }
        return w;
    }
};
